ValidationRule.errorConditionFormula:
ISPICKVAL(PRIORVALUE(StageName), "Excluded") &&
( ISPICKVAL(StageName, "Draft") || ISPICKVAL(StageName, "Discovery") || ISPICKVAL(StageName, "Solicitation") || ISPICKVAL(StageName, "Committed") || ISPICKVAL(StageName, "Closed") || ISPICKVAL(StageName, "Follow Up") || ISPICKVAL(StageName, "Withdrawn") || ISPICKVAL(StageName, "Cancelled")
)
